            StockLevel(product.sku, product.name, levels.get(product.sku, 0))
            for product in self._catalog.list_all()
            if product.active and levels.get(product.sku, 0) < threshold
        ]
        return sorted(below, key=lambda level: (level.on_hand, level.sku))

    def packing_slip(self, order_id: str) -> PackingSlip:
        """Build the packing slip for an order, with lines in the order's item order."""
        order = self._orders.get(order_id)
        if order is None:
            raise OrderNotFound(order_id)
        if order.status == "cancelled":
            raise Conflict("order is cancelled")
        customer = self._customers.get(order.customer_id)
        if customer is None:
            raise CustomerNotFound(order.customer_id)
        lines = []
        for item in order.items:
            product = self._catalog.get(item.sku)
            if product is None:
                raise ProductNotFound(item.sku)
            lines.append(PackingSlipLine(item.sku, product.name, item.quantity))
